mapper.select:
SELECT EXISTS(SELECT 1 FROM memory_change WHERE tenant_id = #{tenantId}
  AND actor_type = 'LEGACY_MIGRATION'
  AND idempotency_key = CONCAT('legacy-adopted:', #{memoryId}, ':topic'))

SELECT m.* FROM memory m WHERE m.status = 'ADOPTED' AND m.is_deleted = 0
  AND m.id > #{afterId} AND 
ORDER BY m.id LIMIT #{limit}

SELECT * FROM memory

    tenant_id = #{tenantId} AND is_deleted = 0
    AND scope = #{scope}
    AND owner_ref = #{ownerRef}
    AND type = #{type}

        AND status = #{status}
        AND status <> 'REJECTED'


        AND (scope <> 'AGENT' OR owner_ref = #{visibleAgentRef})


        AND (title LIKE CONCAT('%', #{keyword}, '%')
            OR content_md LIKE CONCAT('%', #{keyword}, '%'))


ORDER BY id DESC LIMIT #{offset}, #{limit}

SELECT COUNT(*) FROM memory

    tenant_id = #{tenantId} AND is_deleted = 0
    AND scope = #{scope}
    AND owner_ref = #{ownerRef}
    AND type = #{type}

        AND status = #{status}
        AND status <> 'REJECTED'

mapper.update:
UPDATE memory SET title = #{title}, content_md = #{contentMd}, type = #{type},
    version = version + 1, modifier_id = #{modifierId}
WHERE id = #{id} AND tenant_id = #{tenantId} AND version = #{version} AND is_deleted = 0

mapper.select:
SELECT scope, owner_ref, COUNT(*) AS total, MAX(id) AS latest_id FROM memory

    tenant_id = #{tenantId} AND is_deleted = 0
    AND scope = #{scope}
    AND owner_ref = #{ownerRef}
    AND type = #{type}

        AND status = #{status}
        AND status <> 'REJECTED'


GROUP BY scope, owner_ref
ORDER BY latest_id DESC
LIMIT #{offset}, #{limit}

SELECT COUNT(*) FROM (
    SELECT scope, owner_ref FROM memory

        tenant_id = #{tenantId} AND is_deleted = 0
        AND scope = #{scope}
        AND owner_ref = #{ownerRef}
        AND type = #{type}

            AND status = #{status}
            AND status <> 'REJECTED'


    GROUP BY scope, owner_ref
) grouped_memory

SELECT * FROM memory
WHERE tenant_id = #{tenantId} AND is_deleted = 0
AND type = #{type}

    AND status = #{status}
    AND status <> 'REJECTED'

AND

    (scope = #{g.scope} AND

        owner_ref = #{g.ownerRef}
        owner_ref IS NULL
    )

ORDER BY id DESC
LIMIT #{limit}

SELECT m.* FROM memory m
WHERE m.tenant_id = #{tenantId}
  AND m.status = 'ADOPTED'
  AND m.is_deleted = 0
  AND (
    m.scope = 'ORG'
    OR (m.scope = 'AGENT' AND m.owner_ref = #{agentId})
    OR (m.scope = 'SQUAD' AND EXISTS (
        SELECT 1 FROM squad_member sm
        WHERE sm.tenant_id = #{tenantId}
          AND sm.squad_id = m.owner_ref
          AND sm.agent_id = #{agentId}
    ))
  )
ORDER BY m.id ASC
